body:
开始 Winsock 编程，先把最小生命周期写完整，再增加连接和收发。下面程序只创建并释放一个未连接 TCP 套接字，用于阅读初始化与清理顺序。

~~~cpp
#include <winsock2.h>
#include <iostream>
#pragma comment(lib, "Ws2_32.lib")
int main() {
    WSADATA data{};
    const int start = WSAStartup(MAKEWORD(2, 2), &data);
    if (start != 0) { std::cerr << "startup: " << start << '\n'; return 1; }
    if (LOBYTE(data.wVersion) != 2 || HIBYTE(data.wVersion) != 2) {
        WSACleanup();
        return 1;
    }
    SOCKET socketValue = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (socketValue == INVALID_SOCKET) {
        const int error = WSAGetLastError();
        std::cerr << "socket: " << error << '\n';
        WSACleanup();
        return 1;
    }
    const int closed = closesocket(socketValue);
    const int closeError = closed == SOCKET_ERROR ? WSAGetLastError() : 0;
    const int cleaned = WSACleanup();
    if (closed == SOCKET_ERROR || cleaned == SOCKET_ERROR) {
        std::cerr << "cleanup failed, socket error=" << closeError << '\n';
        return 1;
    }
    std::cout << "created and released\n";
}
~~~

成功路径先初始化、创建、关闭，再清理库。创建失败时没有有效套接字可关闭，但已经成功初始化的库仍需要清理；初始化失败时则不把一次失败调用计为需要配对清理的成功会话。

在更长程序中，手工为每条失败路径重复清理容易遗漏，后面的公共头文件会让资源所有者自动管理它们。本例先把阶段展开，是为了明确“取得了什么才清理什么”。

没有连接的套接字不能直接按已连接 TCP 端点收业务数据。创建成功也不代表某个端口已绑定、正在监听或已经连接对端；每个状态都必须由后续成功操作建立。

字节序说明多字节整数怎样按字节排列。TCP/IP 网络序使用高有效字节在前；主机内部表示可能不同。转换是为了让双方依据同一规则解释数值，不是把十进制改成十六进制显示。

例如长度 258 等于十六进制 0102，网络上的两个八位组是 01、02。接收端组合为 `1*256+2`，仍得到 258。不要拿两端主机内存里的 ushort 直接发送而忽略约定。

~~~cpp
#include <array>
#include <iostream>
int main() {
    const unsigned int length = 258;
    std::array<unsigned char, 2> bytes{
        static_cast<unsigned char>(length >> 8),
        static_cast<unsigned char>(length & 255)
    };
    const unsigned int restored = static_cast<unsigned int>(bytes[0]) * 256 + bytes[1];
    std::cout << static_cast<unsigned int>(bytes[0]) << ' '
              << static_cast<unsigned int>(bytes[1]) << ' ' << restored << '\n';
}
~~~

显示 `1 2 258`。这是字段编码的独立阅读例；本章 Windows 网络环境使用八位字节。处理其他目标时，还应明确协议八位组与 C++ 字节的对应条件。

Winsock 的 htons/ntohs 处理16位数，htonl/ntohl 处理32位数。端口 4600 应先 htons 再放入 sockaddr_in 的端口字段。不要看到函数名的 long 就套用任意平台 long 的大小，接口在 Winsock 中有其规定宽度。

字符串的字节不需要整体“倒序”处理，但字符串编码仍须约定。结构体更不能用一次整数转换解决所有布局问题，应逐字段规定格式与范围。

把业务命令变成明确协议，双方才知道何时回应、何时结束。本章沿用教材的欢迎信息与 A/C 命令，增加两字节网络序长度前缀，正文最多1024字节。

|消息方向|正文|含义|
|---|---|---|
|服务端→客户端|THIS IS SERVER|连接后欢迎信息|
|客户端→服务端|A / C|分别请求 B / D|
|客户端→服务端|其他正文|服务端回答 ERR|
|客户端→服务端|exit|服务端回答 BYE 后结束本次会话|

所有正文，包括欢迎和 BYE，都用同一种帧。正文 A 的线格式是两个头字节 00 01 加一个 A；exit 是 00 04 加四个字符。接收端先精确取得两个头字节，验证长度，再精确取得正文，不把 TCP 的一次 recv 当完整消息。

下面保存为公共头文件 lesson_net.hpp。它与后面两个独立源文件一起阅读；server.cpp 与 client.cpp 分别是两个程序，不能把两个 main 塞进同一个工程。代码使用 Windows Winsock 与 MSVC 链接指示，不是跨平台标准 C++ 网络库。

~~~cpp
#pragma once
#include <winsock2.h>
#include <iostream>
#include <stdexcept>
#include <string>
#pragma comment(lib, "Ws2_32.lib")
namespace lesson {
[[noreturn]] inline void networkError(const char* operation) {
    const int code = WSAGetLastError();
    throw std::runtime_error(std::string(operation) + ": " + std::to_string(code));
}
class Session {
public:
    Session() {
        WSADATA data{};
        const int code = WSAStartup(MAKEWORD(2, 2), &data);
        if (code != 0) throw std::runtime_error("WSAStartup: " + std::to_string(code));
        if (LOBYTE(data.wVersion) != 2 || HIBYTE(data.wVersion) != 2) {
            WSACleanup();
            throw std::runtime_error("Winsock 2.2 unavailable");
        }
    }
    ~Session() { WSACleanup(); }
    Session(const Session&) = delete;
    Session& operator=(const Session&) = delete;
};
class Socket {
    SOCKET value;
public:
    explicit Socket(SOCKET handle) : value(handle) {
        if (value == INVALID_SOCKET) networkError("socket/accept");
    }
    ~Socket() { closesocket(value); }
    Socket(const Socket&) = delete;
    Socket& operator=(const Socket&) = delete;
    SOCKET native() const { return value; }
};
inline sockaddr_in loopback(unsigned short port) {
    sockaddr_in address{};
    address.sin_family = AF_INET;
    address.sin_port = htons(port);
    address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    return address;
}
inline void sendAll(SOCKET socketValue, const char* data, int length) {
    int done = 0;
    while (done < length) {
        const int count = send(socketValue, data + done, length - done, 0);
        if (count == SOCKET_ERROR) networkError("send");
        if (count == 0) throw std::runtime_error("send made no progress");
        done += count;
    }
}
inline void readExact(SOCKET socketValue, char* data, int length) {
    int done = 0;
    while (done < length) {
        const int count = recv(socketValue, data + done, length - done, 0);
        if (count == SOCKET_ERROR) networkError("recv");
        if (count == 0) throw std::runtime_error("peer closed before frame finished");
        done += count;
    }
}
inline void sendFrame(SOCKET socketValue, const std::string& message) {
    if (message.size() > 1024) throw std::runtime_error("frame too large");
    const int length = static_cast<int>(message.size());
    const char header[2]{static_cast<char>(length >> 8), static_cast<char>(length & 255)};
    sendAll(socketValue, header, 2);
    sendAll(socketValue, message.data(), length);
}
inline std::string readFrame(SOCKET socketValue) {
    char header[2];
    readExact(socketValue, header, 2);
    const int length = static_cast<unsigned char>(header[0]) * 256
                     + static_cast<unsigned char>(header[1]);
    if (length > 1024) throw std::runtime_error("frame too large");
    std::string message(static_cast<std::size_t>(length), '\0');
    readExact(socketValue, message.data(), length);
    return message;
}
}
~~~

Session 必须比它管理期间的套接字先创建、后销毁，所以源文件先声明 session 再声明 socket。Socket 禁止复制，避免两个所有者重复关闭同一个句柄。析构函数负责最后清理，不向外抛异常；它们没有声称关闭等于所有远端业务已经完成。

readExact 只负责取得给定数量，不会擅自吃掉下一帧；零正文长度可以返回空字符串，而对端在需要头或正文时关闭会报告不完整。1024 上限在申请正文存储前检查，防止直接按对方声明的任意长度分配。

这些函数用于阻塞、顺序访问的套接字，没有自动超时或线程同步。需要非阻塞、多个并行写入或生产级恢复时，应另建状态机和明确错误契约，不能直接把这几个循环原样当成通用通信框架。

服务端的职责是绑定端点、接纳连接、发送欢迎信息，再逐条处理请求。先把一个客户端完整服务好，才能看清监听套接字与连接套接字的分工。

下面 server.cpp 包含上一节完整的 lesson_net.hpp，作为单独控制台程序。它只绑定本机回环 127.0.0.1:4600，处理一个客户端的连续消息，收到 exit 后退出。

~~~cpp
#include "lesson_net.hpp"
int main() {
    try {
        lesson::Session session;
        lesson::Socket listener(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP));
        sockaddr_in address = lesson::loopback(4600);
        if (bind(listener.native(), reinterpret_cast<const sockaddr*>(&address),
                 static_cast<int>(sizeof(address))) == SOCKET_ERROR)
            lesson::networkError("bind");
        if (listen(listener.native(), SOMAXCONN) == SOCKET_ERROR)
            lesson::networkError("listen");
        std::cout << "waiting on loopback:4600\n";
        lesson::Socket peer(accept(listener.native(), nullptr, nullptr));
        std::cout << "client connected\n";
        lesson::sendFrame(peer.native(), "THIS IS SERVER");
        for (;;) {
            const std::string request = lesson::readFrame(peer.native());
            std::cout << "request=" << request << '\n';
            if (request == "exit") {
                lesson::sendFrame(peer.native(), "BYE");
                break;
            }
            const std::string answer = request == "A" ? "B"
                                     : request == "C" ? "D" : "ERR";
            lesson::sendFrame(peer.native(), answer);
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
~~~

listener 在 accept 后仍存在，实际收发使用 peer。失败时异常离开作用域，已经构造的 peer、listener 按逆序关闭，最后 session 清理 Winsock。accept 自身失败时不会产生一个需要关闭的有效 peer。

连续请求 A、C、bad、exit，对应回复 B、D、ERR、BYE。未知命令不会直接终止整个服务，结束命令则先送出协议回应再离开循环。若长度头不完整、正文超限或连接中途关闭，会进入错误路径，不再把未完成数据当完整命令。

教材还展示最多20个客户端的线程方案。扩展时应让每个工作线程独占自己的连接，明确活动数怎样在成功接纳后增加、退出后减少，满额时怎样拒绝，并在所有工作线程结束后才清理库。不能先把新连接写到固定数组第20个下标，再检查是否超过容量；也不能把线程句柄和套接字的释放混为一谈。本例先集中展示协议与资源生命周期，不冒称已实现这套并发管理。

客户端需要先连接到与服务端一致的地址和端口，再按协议等待欢迎信息、发送请求并读取回应。双方若都先等待对方发送，就可能各自阻塞；如果一方按长度前缀而另一方按裸字符串，数据即使到达也无法正确解析。

下面 client.cpp 与服务端共享 lesson_net.hpp，但应作为另一个程序构建。为了让完整过程可手算，本例依次发送固定 A、C、bad、exit，不让终端输入规则干扰第一次理解。

~~~cpp
#include "lesson_net.hpp"
int main() {
    try {
        lesson::Session session;
        lesson::Socket connection(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP));
        sockaddr_in address = lesson::loopback(4600);
        if (connect(connection.native(), reinterpret_cast<const sockaddr*>(&address),
                    static_cast<int>(sizeof(address))) == SOCKET_ERROR)
            lesson::networkError("connect");
        std::cout << "welcome=" << lesson::readFrame(connection.native()) << '\n';
        const char* requests[]{"A", "C", "bad", "exit"};
        for (const char* request : requests) {
            lesson::sendFrame(connection.native(), request);
            const std::string answer = lesson::readFrame(connection.native());
            std::cout << request << " -> " << answer << '\n';
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
~~~

协议成功时，客户端显示欢迎内容，以及 A→B、C→D、bad→ERR、exit→BYE。读取 BYE 后，客户端正常离开作用域关闭连接。它没有把 send 成功当成请求已经处理，而是明确等待对应应用回应。

如果希望恢复教材的交互输入，可在欢迎信息之后用 getline 读一行，验证长度，再发送并等待一帧回应；输入 exit 后收到 BYE 就结束，不再继续发送。终端 EOF 也是需要定义的结束路径，可选择发送结束命令或明确关闭，不能无限使用上一条命令。

connect 失败时应立即报告并清理，不能继续 recv 然后把新的错误当成最初原因。两端同时运行的屏幕日志可能交错，不应把跨进程屏幕先后当作协议的精确时间证明。

这份阻塞客户端没有重连、截止时间、认证和加密。若要实现真实远程业务，还要为这些需求单独设计；当前例子已经足以说明消息边界、请求回应和局部资源清理。

第一项练习是在客户端接入时显示提示并反馈。前面的服务端在 accept 成功后输出 client connected，再发送 THIS IS SERVER 帧，已经形成完整示范。可以进一步添加业务会话号，但要说明它由应用分配，不要把易复用的套接字数值当永久用户身份。

第二项练习改用 UDP。为看清差异，先做回环上的单次 A→B 数据报，再考虑多条聊天。下面两个程序复用 lesson_net.hpp 中的 Session、Socket、loopback，使用不同端口4601；它们不使用 TCP 的长度帧函数。

UDP 服务端单独源文件：

~~~cpp
#include "lesson_net.hpp"
int main() {
    try {
        lesson::Session session;
        lesson::Socket socketValue(socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP));
        sockaddr_in address = lesson::loopback(4601);
        if (bind(socketValue.native(), reinterpret_cast<const sockaddr*>(&address),
                 static_cast<int>(sizeof(address))) == SOCKET_ERROR)
            lesson::networkError("UDP bind");
        char buffer[1024];
        sockaddr_in sender{};
        int senderSize = static_cast<int>(sizeof(sender));
        const int count = recvfrom(socketValue.native(), buffer, 1024, 0,
                                   reinterpret_cast<sockaddr*>(&sender), &senderSize);
        if (count == SOCKET_ERROR) lesson::networkError("recvfrom");
        const std::string request(buffer, static_cast<std::size_t>(count));
        const std::string answer = request == "A" ? "B" : "ERR";
        const int sent = sendto(socketValue.native(), answer.data(),
                                static_cast<int>(answer.size()), 0,
                                reinterpret_cast<const sockaddr*>(&sender), senderSize);
        if (sent == SOCKET_ERROR) lesson::networkError("sendto");
        if (sent != static_cast<int>(answer.size())) throw std::runtime_error("incomplete datagram");
        std::cout << "answered " << request << " -> " << answer << '\n';
    } catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 1; }
}
~~~

UDP 客户端单独源文件：

~~~cpp
#include "lesson_net.hpp"
int main() {
    try {
        lesson::Session session;
        lesson::Socket socketValue(socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP));
        sockaddr_in server = lesson::loopback(4601);
        const char request = 'A';
        const int sent = sendto(socketValue.native(), &request, 1, 0,
                                reinterpret_cast<const sockaddr*>(&server),
                                static_cast<int>(sizeof(server)));
        if (sent == SOCKET_ERROR) lesson::networkError("sendto");
        if (sent != 1) throw std::runtime_error("incomplete datagram");
        char buffer[1024];
        sockaddr_in sender{};
        int senderSize = static_cast<int>(sizeof(sender));
        const int count = recvfrom(socketValue.native(), buffer, 1024, 0,
                                   reinterpret_cast<sockaddr*>(&sender), &senderSize);
        if (count == SOCKET_ERROR) lesson::networkError("recvfrom");
        if (sender.sin_family != AF_INET || sender.sin_port != server.sin_port
            || sender.sin_addr.s_addr != server.sin_addr.s_addr)
            throw std::runtime_error("unexpected sender");
        std::cout << std::string(buffer, static_cast<std::size_t>(count)) << '\n';
    } catch (const std::exception& e) { std::cerr << e.what() << '\n'; return 1; }
}
~~~

两端和数据报传送成功时，客户端显示 B，服务端报告 A→B。recvfrom 用实际 count 建立字符串，不要求数组末尾 NUL；count 为0时也不会被当作 TCP 断线。消息超出1024导致 WSAEMSGSIZE 时会走失败路径，不把截断内容当作完整请求。

这两个阻塞程序没有超时与重传：包丢失或对端未启动时可能一直等待。把它扩为聊天，至少还需消息标识、来源验证、重复处理、结束约定和等待截止；单纯把循环无限重复，并没有获得可靠、有序的聊天服务。先为这些情况写出协议规则，再考虑并发界面。
